-- Migration: 20261004000000_migrate_profiles_and_entities_to_integer_id.sql
-- Description: Comprehensive migration to integer primary keys (bigint generated by default as identity)
-- for profiles, allowed_members, diaries, diary_entries, goals, tasks, user_items, and document junctions.
-- Preserves auth.users foreign key mapping via `profiles.auth_user_id (uuid unique)`.

-- ==============================================================================
-- 1. DROP EXISTING DEPENDENT OBJECTS (CLEAN REBUILD FOR NUMERIC IDENTIFIERS)
-- ==============================================================================

-- Drop triggers
drop trigger if exists on_auth_user_created on auth.users;
drop trigger if exists on_profiles_updated on public.profiles;
drop trigger if exists on_user_items_updated on public.user_items;
drop trigger if exists on_diaries_updated on public.diaries;
drop trigger if exists on_diary_entries_updated on public.diary_entries;
drop trigger if exists set_goals_updated_at on public.goals;
drop trigger if exists set_tasks_updated_at on public.tasks;
drop trigger if exists on_tag_categories_updated on public.tag_categories;
drop trigger if exists on_tags_updated on public.tags;

-- Drop tables in dependency order
drop table if exists public.task_tags cascade;
drop table if exists public.tasks cascade;
drop table if exists public.goal_tags cascade;
drop table if exists public.goals cascade;
drop table if exists public.diary_entry_tags cascade;
drop table if exists public.document_tags cascade;
drop table if exists public.tags cascade;
drop table if exists public.tag_categories cascade;
drop table if exists public.diary_entries cascade;
drop table if exists public.diaries cascade;
drop table if exists public.user_items cascade;
drop table if exists public.allowed_members cascade;
drop table if exists public.profiles cascade;

-- ==============================================================================
-- 2. CREATE SCHEMAS WITH INTEGER / BIGINT IDENTIFIERS
-- ==============================================================================

-- 2.1 Profiles Table (Integer ID PK, auth_user_id FK to auth.users)
create table public.profiles (
  id bigint generated by default as identity primary key,
  auth_user_id uuid unique references auth.users(id) on delete cascade,
  email text not null unique,
  full_name text,
  username text unique,
  avatar_url text,
  bio text,
  role text not null default 'member' check (role in ('admin', 'member', 'guest')),
  sort_preferences jsonb not null default jsonb_build_object(
    'default_sort_by', 'created_at',
    'default_sort_order', 'desc',
    'filter_favorites_first', true
  ),
  email_preferences jsonb not null default jsonb_build_object(
    'marketing', false,
    'transactional', true,
    'newsletter', true,
    'product_updates', true,
    'digest_frequency', 'weekly'
  ),
  display_settings jsonb not null default jsonb_build_object(
    'theme', 'system',
    'density', 'comfortable',
    'view_mode', 'grid'
  ),
  metadata jsonb not null default jsonb_build_object(
    'residence', 'Archival Broadside',
    'clearance_title', 'Level II Scribe',
    'ritual_streak_days', 0,
    'unlocked_stamps', jsonb_build_array('founding_scribe')
  ),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 2.2 Allowed Members Table (Integer ID PK)
create table public.allowed_members (
  id bigint generated by default as identity primary key,
  email text not null unique,
  added_by bigint references public.profiles(id) on delete set null,
  status text not null default 'active' check (status in ('active', 'suspended', 'revoked')),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 2.3 User Items Table (Integer ID PK, Integer user_id FK)
create table public.user_items (
  id bigint generated by default as identity primary key,
  user_id bigint not null references public.profiles(id) on delete cascade,
  title text not null,
  description text,
  category text,
  status text not null default 'active' check (status in ('active', 'archived', 'draft')),
  sort_order integer not null default 0,
  is_pinned boolean not null default false,
  is_favorite boolean not null default false,
  tags text[] not null default '{}',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 2.4 Diaries Table (Integer ID PK, Integer user_id FK)
create table public.diaries (
  id bigint generated by default as identity primary key,
  user_id bigint not null references public.profiles(id) on delete cascade,
  name text not null,
  description text,
  theme text not null default 'vintage' check (theme in ('vintage', 'classic', 'modern')),
  cover_color text default '#8C3A27',
  is_favorite boolean not null default false,
  is_archived boolean not null default false,
  sort_order integer not null default 0,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 2.5 Diary Entries Table (Integer ID PK, Integer diary_id & user_id FKs)
create table public.diary_entries (
  id bigint generated by default as identity primary key,
  diary_id bigint not null references public.diaries(id) on delete cascade,
  user_id bigint not null references public.profiles(id) on delete cascade,
  page_number integer not null default 1,
  entry_date date not null default current_date,
  date_str text not null,
  day_of_week text not null,
  year_str text not null,
  title text not null default '',
  description text not null default '',
  gratitude text[] not null default array['', '', '']::text[],
  energy_level integer not null default 3 check (energy_level between 1 and 5),
  start_time text default '09:00',
  end_time text default '17:00',
  mood text not null default '🌿 Calm',
  weather text not null default 'sunny',
  is_hearted boolean not null default false,
  tags text[] not null default '{}',
  word_count integer not null default 0,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint unique_diary_page_number unique (diary_id, page_number)
);

-- 2.6 Tag Categories & Tags Tables (Integer ID PKs, Integer user_id FK)
create table public.tag_categories (
  id bigint generated by default as identity primary key,
  user_id bigint not null references public.profiles(id) on delete cascade,
  feature text not null default 'general',
  name varchar(50) not null,
  color varchar(7) not null default '#6B7280',
  display_order integer not null default 0,
  is_system boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint uq_user_feature_category_name unique (user_id, feature, name)
);

create table public.tags (
  id bigint generated by default as identity primary key,
  category_id bigint not null references public.tag_categories(id) on delete cascade,
  user_id bigint not null references public.profiles(id) on delete cascade,
  name varchar(50) not null,
  color varchar(7) default null,
  is_system boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint uq_user_tag_in_category unique (category_id, name)
);

-- 2.7 Junctions: Diary Entry Tags & Document Tags (Integer IDs)
create table public.diary_entry_tags (
  entry_id bigint not null references public.diary_entries(id) on delete cascade,
  tag_id bigint not null references public.tags(id) on delete cascade,
  user_id bigint not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),

  primary key (entry_id, tag_id)
);

create table public.document_tags (
  document_id bigint not null,
  tag_id bigint not null references public.tags(id) on delete cascade,
  user_id bigint not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),

  primary key (document_id, tag_id)
);

-- 2.8 Goals & Goal Tags Tables (Integer ID PKs, Integer parent_id & user_id FKs)
create table public.goals (
  id bigint generated by default as identity primary key,
  user_id bigint not null references public.profiles(id) on delete cascade,
  parent_id bigint references public.goals(id) on delete cascade,
  
  title varchar(255) not null,
  description text,
  type public.goal_type not null default 'daily',
  status public.goal_status not null default 'draft',
  priority public.goal_priority not null default 'normal',
  
  start_date timestamptz,
  due_date timestamptz,
  achieved_at timestamptz,
  cancelled_at timestamptz,
  cancel_reason text,
  
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.goal_tags (
  goal_id bigint not null references public.goals(id) on delete cascade,
  tag_id bigint not null references public.tags(id) on delete cascade,
  user_id bigint not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),

  primary key (goal_id, tag_id)
);

-- 2.9 Tasks & Task Tags Tables (Integer ID PKs, Integer parent_id & user_id FKs)
create table public.tasks (
  id bigint generated by default as identity primary key,
  user_id bigint not null references public.profiles(id) on delete cascade,
  parent_id bigint references public.tasks(id) on delete cascade,
  
  title varchar(255) not null,
  description text,
  status public.task_status not null default 'todo',
  priority public.task_priority not null default 'normal',
  
  scheduled_date date,
  due_date timestamptz,
  completed_at timestamptz,
  
  time_estimate_minutes integer check (time_estimate_minutes is null or time_estimate_minutes >= 0),
  actual_minutes integer check (actual_minutes is null or actual_minutes >= 0),
  sort_order integer not null default 0,
  
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.task_tags (
  task_id bigint not null references public.tasks(id) on delete cascade,
  tag_id bigint not null references public.tags(id) on delete cascade,
  user_id bigint not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),

  primary key (task_id, tag_id)
);

