-- Profiles: Map auth.uid() to profiles.auth_user_id
create policy "Users can view own profile"
  on public.profiles for select
  to authenticated
  using (auth_user_id = (select auth.uid()));

create policy "Users can update own profile"
  on public.profiles for update
  to authenticated
  using (auth_user_id = (select auth.uid()))
  with check (auth_user_id = (select auth.uid()));

create policy "Users can insert own profile"
  on public.profiles for insert
  to authenticated
  with check (auth_user_id = (select auth.uid()));

-- Allowed Members: Admins have full access; authenticated users can check their own email
create policy "Admins have full access to allowed_members"
  on public.allowed_members for all
  to authenticated
  using (
    exists (
      select 1 from public.profiles
      where profiles.auth_user_id = (select auth.uid())
        and profiles.role = 'admin'
    )
  )
  with check (
    exists (
      select 1 from public.profiles
      where profiles.auth_user_id = (select auth.uid())
        and profiles.role = 'admin'
    )
  );

create policy "Users can check own email in allowed_members"
  on public.allowed_members for select
  to authenticated
  using (email = (select auth.jwt()->>'email'));

