-- ==============================================================================
-- 5. TRIGGERS & PROCEDURES
-- ==============================================================================

create or replace function public.handle_updated_at()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger on_profiles_updated before update on public.profiles for each row execute function public.handle_updated_at();
create trigger on_user_items_updated before update on public.user_items for each row execute function public.handle_updated_at();
create trigger on_diaries_updated before update on public.diaries for each row execute function public.handle_updated_at();
create trigger on_diary_entries_updated before update on public.diary_entries for each row execute function public.handle_updated_at();
create trigger set_goals_updated_at before update on public.goals for each row execute function public.handle_updated_at();
create trigger set_tasks_updated_at before update on public.tasks for each row execute function public.handle_updated_at();
create trigger on_tag_categories_updated before update on public.tag_categories for each row execute function public.handle_updated_at();
create trigger on_tags_updated before update on public.tags for each row execute function public.handle_updated_at();

-- Trigger: create profile on auth signup with integer profile ID
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  is_admin boolean;
  is_whitelisted boolean;
begin
  select exists(select 1 from public.profiles where email = new.email and role = 'admin') into is_admin;
  select exists(select 1 from public.allowed_members where email = new.email and status = 'active') into is_whitelisted;

  insert into public.profiles (
    auth_user_id,
    email,
    full_name,
    avatar_url,
    role
  )
  values (
    new.id,
    coalesce(new.email, ''),
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', split_part(new.email, '@', 1)),
    coalesce(new.raw_user_meta_data->>'avatar_url', new.raw_user_meta_data->>'picture', ''),
    case when is_admin then 'admin' else 'member' end
  )
  on conflict (auth_user_id) do update set
    email = excluded.email,
    full_name = coalesce(excluded.full_name, profiles.full_name),
    avatar_url = coalesce(excluded.avatar_url, profiles.avatar_url),
    updated_at = now();

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row
  execute function public.handle_new_user();

-- ==============================================================================
-- 6. RPC PROCEDURES WITH NUMERIC IDENTIFIERS
-- ==============================================================================

-- 6.1 get_diary_stats
create or replace function public.get_diary_stats(
  p_diary_id bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile_id bigint;
  v_total_entries integer := 0;
  v_total_words integer := 0;
  v_avg_energy numeric := 0;
  v_hearted_count integer := 0;
  v_current_streak integer := 0;
  v_longest_streak integer := 0;
  v_mood_breakdown jsonb := '{}'::jsonb;
  v_all_tags text[] := '{}'::text[];
  v_prev_date date;
  v_curr_streak_calc integer := 0;
  v_r record;
begin
  select id into v_profile_id from public.profiles where auth_user_id = auth.uid();
  if v_profile_id is null then
    raise exception 'Not authenticated';
  end if;

  select
    count(*),
    coalesce(sum(word_count), 0),
    coalesce(round(avg(energy_level), 2), 0),
    count(*) filter (where is_hearted = true)
  into
    v_total_entries,
    v_total_words,
    v_avg_energy,
    v_hearted_count
  from public.diary_entries
  where user_id = v_profile_id
    and (p_diary_id is null or diary_id = p_diary_id);

  select jsonb_object_agg(mood, mood_count)
  into v_mood_breakdown
  from (
    select mood, count(*) as mood_count
    from public.diary_entries
    where user_id = v_profile_id
      and (p_diary_id is null or diary_id = p_diary_id)
    group by mood
  ) moods;

  select coalesce(array_agg(distinct tag), '{}'::text[])
  into v_all_tags
  from public.diary_entries,
       unnest(tags) as tag
  where user_id = v_profile_id
    and (p_diary_id is null or diary_id = p_diary_id);

  v_prev_date := null;
  for v_r in (
    select distinct entry_date
    from public.diary_entries
    where user_id = v_profile_id
    order by entry_date desc
  ) loop
    if v_prev_date is null then
      if v_r.entry_date = current_date or v_r.entry_date = current_date - 1 then
        v_curr_streak_calc := 1;
        v_current_streak := 1;
      else
        v_curr_streak_calc := 1;
      end if;
    elsif v_prev_date - v_r.entry_date = 1 then
      v_curr_streak_calc := v_curr_streak_calc + 1;
      if v_current_streak > 0 then
        v_current_streak := v_curr_streak_calc;
      end if;
    else
      v_curr_streak_calc := 1;
    end if;

    if v_curr_streak_calc > v_longest_streak then
      v_longest_streak := v_curr_streak_calc;
    end if;

    v_prev_date := v_r.entry_date;
  end loop;

  return jsonb_build_object(
    'total_entries', v_total_entries,
    'total_words', v_total_words,
    'average_energy', v_avg_energy,
    'hearted_entries', v_hearted_count,
    'current_streak', v_current_streak,
    'longest_streak', v_longest_streak,
    'mood_breakdown', coalesce(v_mood_breakdown, '{}'::jsonb),
    'tags', v_all_tags
  );
end;
$$;

-- 6.2 get_user_diaries_overview
create or replace function public.get_user_diaries_overview()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile_id bigint;
  v_result jsonb;
begin
  select id into v_profile_id from public.profiles where auth_user_id = auth.uid();
  if v_profile_id is null then
    raise exception 'Not authenticated';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', d.id,
        'name', d.name,
        'description', d.description,
        'theme', d.theme,
        'cover_color', d.cover_color,
        'is_favorite', d.is_favorite,
        'is_archived', d.is_archived,
        'sort_order', d.sort_order,
        'entries_count', coalesce(stats.entries_count, 0),
        'highest_page_number', coalesce(stats.highest_page_number, 0),
        'latest_entry_date', stats.latest_entry_date,
        'created_at', d.created_at,
        'updated_at', d.updated_at
      ) order by d.is_favorite desc, d.sort_order asc, d.created_at desc
    ),
    '[]'::jsonb
  )
  into v_result
  from public.diaries d
  left join lateral (
    select
      count(*)::int as entries_count,
      max(page_number)::int as highest_page_number,
      max(entry_date) as latest_entry_date
    from public.diary_entries e
    where e.diary_id = d.id and e.user_id = v_profile_id
  ) stats on true
  where d.user_id = v_profile_id;

  return v_result;
end;
$$;

-- 6.3 reorder_diaries
create or replace function public.reorder_diaries(
  p_diary_ids bigint[]
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile_id bigint;
  i integer;
begin
  select id into v_profile_id from public.profiles where auth_user_id = auth.uid();
  if v_profile_id is null then
    raise exception 'Not authenticated';
  end if;

  if p_diary_ids is null or array_length(p_diary_ids, 1) = 0 then
    return;
  end if;

  for i in 1 .. array_length(p_diary_ids, 1) loop
    update public.diaries
    set sort_order = i,
        updated_at = now()
    where id = p_diary_ids[i]
      and user_id = v_profile_id;
  end loop;
end;
$$;

-- 6.4 create_diary_with_first_page
create or replace function public.create_diary_with_first_page(
  p_name text,
  p_description text default null,
  p_theme text default 'vintage',
  p_cover_color text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile_id bigint;
  v_diary_id bigint;
  v_entry_id bigint;
  v_today date := current_date;
  v_date_str text;
  v_day_of_week text;
  v_year_str text;
  v_cover_color text;
  v_result jsonb;
begin
  select id into v_profile_id from public.profiles where auth_user_id = auth.uid();
  if v_profile_id is null then
    raise exception 'Not authenticated';
  end if;

  v_cover_color := coalesce(p_cover_color, case 
    when p_theme = 'vintage' then '#8C3A27'
    when p_theme = 'classic' then '#1E3A5F'
    else '#172330'
  end);

  v_date_str := to_char(v_today, 'FMMonth FMDD');
  v_day_of_week := to_char(v_today, 'FMDay');
  v_year_str := 'Anno ' || to_char(v_today, 'YYYY');

  insert into public.diaries (
    user_id,
    name,
    description,
    theme,
    cover_color,
    is_favorite,
    is_archived
  ) values (
    v_profile_id,
    coalesce(nullif(trim(p_name), ''), 'Untitled Tome'),
    p_description,
    coalesce(p_theme, 'vintage'),
    v_cover_color,
    false,
    false
  )
  returning id into v_diary_id;

  insert into public.diary_entries (
    diary_id,
    user_id,
    page_number,
    entry_date,
    date_str,
    day_of_week,
    year_str,
    title,
    description,
    gratitude,
    energy_level,
    start_time,
    end_time,
    mood,
    weather,
    is_hearted,
    tags
  ) values (
    v_diary_id,
    v_profile_id,
    1,
    v_today,
    v_date_str,
    v_day_of_week,
    v_year_str,
    '',
    '',
    array['', '', '']::text[],
    3,
    '09:00',
    '17:00',
    '🌿 Calm',
    'sunny',
    false,
    array['Fresh Inscription']::text[]
  )
  returning id into v_entry_id;

  select jsonb_build_object(
    'id', d.id,
    'user_id', d.user_id,
    'name', d.name,
    'description', d.description,
    'theme', d.theme,
    'cover_color', d.cover_color,
    'is_favorite', d.is_favorite,
    'is_archived', d.is_archived,
    'sort_order', d.sort_order,
    'entries_count', 1,
    'highest_page_number', 1,
    'latest_entry_date', v_today,
    'created_at', d.created_at,
    'updated_at', d.updated_at,
    'first_entry_id', v_entry_id
  )
  into v_result
  from public.diaries d
  where d.id = v_diary_id;

  return v_result;
end;
$$;

-- 6.5 create_diary_entry
create or replace function public.create_diary_entry(
  p_diary_id bigint,
  p_title text default '',
  p_description text default '',
  p_gratitude text[] default array['', '', '']::text[],
  p_energy_level integer default 3,
  p_start_time text default '09:00',
  p_end_time text default '17:00',
  p_mood text default '🌿 Calm',
  p_weather text default 'sunny',
  p_is_hearted boolean default false,
  p_tags text[] default array['Daily Reflection']::text[]
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile_id bigint;
  v_next_page int;
  v_today date := current_date;
  v_date_str text;
  v_day_of_week text;
  v_year_str text;
  v_entry record;
begin
  select id into v_profile_id from public.profiles where auth_user_id = auth.uid();
  if v_profile_id is null then
    raise exception 'Not authenticated';
  end if;

  select coalesce(max(page_number), 0) + 1
  into v_next_page
  from public.diary_entries
  where diary_id = p_diary_id and user_id = v_profile_id;

  v_date_str := to_char(v_today, 'FMMonth FMDD');
  v_day_of_week := to_char(v_today, 'FMDay');
  v_year_str := 'Anno ' || to_char(v_today, 'YYYY');

  insert into public.diary_entries (
    diary_id,
    user_id,
    page_number,
    entry_date,
    date_str,
    day_of_week,
    year_str,
    title,
    description,
    gratitude,
    energy_level,
    start_time,
    end_time,
    mood,
    weather,
    is_hearted,
    tags
  ) values (
    p_diary_id,
    v_profile_id,
    v_next_page,
    v_today,
    v_date_str,
    v_day_of_week,
    v_year_str,
    coalesce(p_title, ''),
    coalesce(p_description, ''),
    coalesce(p_gratitude, array['', '', '']::text[]),
    coalesce(p_energy_level, 3),
    coalesce(p_start_time, '09:00'),
    coalesce(p_end_time, '17:00'),
    coalesce(p_mood, '🌿 Calm'),
    coalesce(p_weather, 'sunny'),
    coalesce(p_is_hearted, false),
    coalesce(p_tags, array['Daily Reflection']::text[])
  )
  returning * into v_entry;

  return to_jsonb(v_entry);
end;
$$;

-- 6.6 provision_feature_tag_categories
create or replace function public.provision_feature_tag_categories(p_feature text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile_id bigint;
  v_count int;
  v_cat_id bigint;
begin
  select id into v_profile_id from public.profiles where auth_user_id = auth.uid();
  if v_profile_id is null then
    return jsonb_build_object('success', false, 'error', 'User not authenticated');
  end if;

  select count(*) into v_count
  from public.tag_categories
  where user_id = v_profile_id and feature = p_feature;

  if v_count = 0 then
    if p_feature = 'diary' then
      insert into public.tag_categories (user_id, feature, name, color, display_order, is_system)
      values (v_profile_id, 'diary', 'Context', '#3B82F6', 1, true)
      on conflict (user_id, feature, name) do nothing
      returning id into v_cat_id;
      
      if v_cat_id is null then
        select id into v_cat_id from public.tag_categories where user_id = v_profile_id and feature = 'diary' and name = 'Context';
      end if;

      if v_cat_id is not null then
        insert into public.tags (category_id, user_id, name, is_system)
        values 
          (v_cat_id, v_profile_id, 'Deep Work', true),
          (v_cat_id, v_profile_id, 'Reflections', true),
          (v_cat_id, v_profile_id, 'Planning', true)
        on conflict (category_id, name) do nothing;
      end if;

      insert into public.tag_categories (user_id, feature, name, color, display_order, is_system)
      values (v_profile_id, 'diary', 'Energy Level', '#10B981', 2, true)
      on conflict (user_id, feature, name) do nothing
      returning id into v_cat_id;

      if v_cat_id is null then
        select id into v_cat_id from public.tag_categories where user_id = v_profile_id and feature = 'diary' and name = 'Energy Level';
      end if;

      if v_cat_id is not null then
        insert into public.tags (category_id, user_id, name, is_system)
        values 
          (v_cat_id, v_profile_id, 'High Vitality', true),
          (v_cat_id, v_profile_id, 'Medium Vitality', true),
          (v_cat_id, v_profile_id, 'Rest & Recovery', true)
        on conflict (category_id, name) do nothing;
      end if;

    elsif p_feature = 'document' then
      insert into public.tag_categories (user_id, feature, name, color, display_order, is_system)
      values (v_profile_id, 'document', 'Department', '#8B5CF6', 1, true)
      on conflict (user_id, feature, name) do nothing
      returning id into v_cat_id;

      if v_cat_id is null then
        select id into v_cat_id from public.tag_categories where user_id = v_profile_id and feature = 'document' and name = 'Department';
      end if;

      if v_cat_id is not null then
        insert into public.tags (category_id, user_id, name, is_system)
